"""Migration of the legacy opportunity_pipeline workflow."""

from decimal import Decimal
from typing import Any


def _amount_is_positive(value: Any) -> bool:
    """Implement NVL(AMT, 0) > 0 with legacy empty-value coercion."""
    if value is None or value == "":
        return False
    try:
        return Decimal(str(value)) > 0
    except (ArithmeticError, ValueError, TypeError):
        return False


def _close_date_is_set(value: Any) -> bool:
    """Implement CLOSE_DT <> '00000000' as string inequality."""
    return str(value if value is not None else "") != "00000000"


def _lost_reason_present(value: Any) -> bool:
    """LOST_RSN <> '' is true only for a non-empty string."""
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity workflow transition."""
    transitions = (
        ("P", "Q", "qualify", "amount"),
        ("Q", "N", "advance", None),
        ("N", "W", "close_won", "close_date"),
        ("P", "L", "close_lost", "lost_reason"),
        ("Q", "L", "close_lost", "lost_reason"),
        ("N", "L", "close_lost", "lost_reason"),
    )

    selected = None
    for transition in transitions:
        from_state, to_state, transition_event, guard = transition
        if state != from_state or event != transition_event:
            continue

        if guard == "amount" and not _amount_is_positive(record.get("AMT", "")):
            continue
        if guard == "close_date" and not _close_date_is_set(
            record.get("CLOSE_DT", "")
        ):
            continue
        if guard == "lost_reason" and not _lost_reason_present(
            record.get("LOST_RSN", "")
        ):
            continue

        selected = transition
        break

    if selected is None:
        return {
            "state": state,
            "record": dict(record),
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    _, resulting_state, _, transition_guard = selected
    updated_record = dict(record)
    audits = []
    notifies = []

    if transition_guard == "amount":
        updated_record["STAGE_PCT"] = "25"
        audits.append("OPP_QUAL")
    elif transition_guard is None:
        updated_record["STAGE_PCT"] = "60"
    elif transition_guard == "close_date":
        updated_record["STAGE_PCT"] = "100"
        audits.append("OPP_WON")
        notifies.append("won_deal")
    elif transition_guard == "lost_reason":
        updated_record["STAGE_PCT"] = "0"
        audits.append("OPP_LOST")

    return {
        "state": resulting_state,
        "record": updated_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
